INSERT INTO seminars(number,title,details,proposal_status,recruitment,phase,source_url,created_at) VALUES
  (32, 'リーマン面ゼミ', '{"theme":"リーマン面","level":"リーマン面については初学、複素解析は仮定","goals":"Forsterの2章までを読み切る","prerequisites":"複素解析","materials":"Forster \"lectures on Riemann surfaces\"","organizer":"理工系学術サークルWathematica有志","format":"対面","venue":"早稲田大学理工キャンパス","period":"2025年7月〜終わるまで","frequency":"週一回","schedule":"未定","conditions":"早稲田大学の学生","currentSize":"5人","capacity":"なし","description":"Forsterを順に読んでいく"}', 'approved', 'open', 'active', 'https://sites.google.com/view/atlasez-semi/0000032-%E3%83%AA%E3%83%BC%E3%83%9E%E3%83%B3%E9%9D%A2%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (31, '歴史・政治学関連読書ゼミ', '{"theme":"歴史（特に近現代）・政治学","level":"初学者～","goals":"歴史・政治学関連の本の読書およびその内容に関する議論を通じて、現代の政治、情勢をより解像度高く理解する","prerequisites":"特になし","materials":"各人による","organizer":"東京大学学生有志","format":"オンライン","venue":"ZOOMないし、ゼミプラットフォームのVC","period":"2025年8月〜","frequency":"不定期","schedule":"参加者の都合による","conditions":"現在の政治についてより深く理解したい、他人と建設的に現在の政治について議論したいという方なら誰でも大歓迎です！","currentSize":"1人","capacity":"なし","description":"昨今、世界中で排外主義的ポピュリズムの隆盛が目立ちます。我々大学生といった未来を担う世代にとってこれは決して看過できない状況である一方で、我々自身このような状況をどのように理解すればいいのか、戸惑うところがあることも事実です。\nしかし、それは一つには我々自身に知識が不足しているところが大きく、このような情勢を深く理解しようと思えば、まずはこうした問題に誰よりも向き合い、知見を積み上げてきた研究者…"}', 'approved', 'open', 'planned', 'https://sites.google.com/view/atlasez-semi/0000031-%E6%AD%B4%E5%8F%B2%E6%94%BF%E6%B2%BB%E5%AD%A6%E9%96%A2%E9%80%A3%E8%AA%AD%E6%9B%B8%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (16, '場の量子論のゼミ', '{"theme":"場の量子論","level":"初学者","goals":"自己完結型の入門資料の作成：第Ⅰ巻の議論と理解を通じて、第Ⅱ巻を理解するために必要な知識を標準化する。","prerequisites":"大学レベルの数学（教養レベル）、日本語（英語に自信があるとなお良い。）","materials":"ワインバーグ 場の量子論 (1巻)-日本語版、または英語版、もしくはその両方","organizer":"University College London学部2年有志","format":"オンライン中心＋対面","venue":"オンライン、UCL＋東京大学","period":"6月上旬〜未定","frequency":"週1回","schedule":"相談の上決定。仮日程: 日曜","conditions":"特になし。東京大学の物理学専攻(学部3年生以上)推奨。","currentSize":"1人","capacity":"5人程度","description":"初学者たちが、非物理学科の人向けに書かれた量子力学の本を読んで基礎的なところから理解することを目指しています"}', 'approved', 'open', 'planned', 'https://sites.google.com/view/atlasez-semi/0000016-%E5%A0%B4%E3%81%AE%E9%87%8F%E5%AD%90%E8%AB%96%E3%81%AE%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (13, '化学ゼミ(1年生)', '{"theme":"化学ゼミ(1年生)","level":"参加者のレベルに合わせる","goals":"化学の様々な分野に関心を持つ。\n化学の内容について理解を深め、学び合う。\n上級生からのアドバイスを受けながら議論を発展させる。","prerequisites":"特に決まっていないが、高校化学の内容を学んでいれば十分","materials":"フォーカスするテーマによって変わる　本やWeb、教科書など","organizer":"ずんだゼミ","format":"対面中心＋オンライン","venue":"東北大学川内or青葉山キャンパスorオンライン","period":"2025年4月上旬から","frequency":"週1回","schedule":"参加者の都合に合わせる","conditions":"大学1年生以上、高校生も可","currentSize":"1人","capacity":"なし","description":"化学について自由に議論できるコミュニティがあればいいなと思い、企画しました。\n毎回、テーマを自由に決め、議論を深めていきます。わいわいと楽しくやるタイプのゼミなので、お気軽にご参加ください。\n大学1年生のレベルを越える知識が必要になる場合が往々にしてありますので、上級生の方にもぜひ参加し、アドバイスしていただきたいです！\nオンラインでの参加も可能です。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000013-%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F1%E5%B9%B4%E7%94%9F', '2026-11-11T00:00:00.000Z'),
  (12, '化学ゼミ(2年生)', '{"theme":"化学ゼミ(2年生)","level":"参加者のレベルに合わせる","goals":"化学の様々な分野に関心を持つ。\n化学の内容について理解を深める。","prerequisites":"特に決まっていないが、大学1年生で学ぶ程度の知識があれば十分","materials":"フォーカスするテーマによって変わる　本やWeb、教科書など","organizer":"ずんだゼミ","format":"対面中心＋オンライン","venue":"東北大学川内or青葉山キャンパスorオンライン","period":"2024年6月上旬から","frequency":"週1回","schedule":"参加者の都合に合わせる","conditions":"誰でも","currentSize":"10人","capacity":"なし","description":"化学について自由に議論できるコミュニティがあればいいなと思い、企画しました。\n毎回、テーマを自由に決め、納得のいくまで議論を深めています。\nわいわいと楽しくやるタイプのゼミなので、お気軽にご参加ください。オンラインでの参加も可能です。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000012-%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F2%E5%B9%B4%E7%94%9F', '2026-11-11T00:00:00.000Z'),
  (10, '多様体の基礎ゼミ', '{"theme":"多様体の基礎","level":"初学者","goals":"多様体の基礎を学習する","prerequisites":"基礎的なレベルの線形代数学、微分積分学、位相空間論","materials":"松本 幸夫「多様体の基礎」","organizer":"駒場理数サークル","format":"対面","venue":"東京大学駒場キャンパス","period":"2024年6月上旬〜未定","frequency":"週1回","schedule":"水曜6限(18:45-20:30)","conditions":"任意","currentSize":"7人","capacity":"特になし","description":"多様体という目新しい対象を知り、扱うこと自体が興味深い。\nゼミ全体で次の分野を見据えたりはしていないが物理や幾何など活きる分野は多くあると思われる。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000010-%E5%A4%9A%E6%A7%98%E4%BD%93%E3%81%AE%E5%9F%BA%E7%A4%8E%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (9, '有機化学ゼミ', '{"theme":"有機化学","level":"初学者","goals":"有機化学の演習問題を解きながら理解を定着させる。また、疑問点について議論することを通してテキスト以上の理解を目指す。","prerequisites":"有機化学に関する学部教養程度の知識","materials":"David R. Klein 著、岩澤　伸治 監訳「クライン有機化学」東京化学同人","organizer":"東北大学自主ゼミサークルずんだゼミ","format":"対面","venue":"東北大学青葉山キャンパス","period":"2024年5月上旬～7月下旬","frequency":"週1回","schedule":"金曜日 14:30-16:00","conditions":"東北大学の学生","currentSize":"4人","capacity":"未定","description":"有機化学の演習を通じて理解の定着を目的として開催しています。教科書の演習問題を毎週解いています。学部1~2年程度を主な対象としています。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000009-%E6%9C%89%E6%A9%9F%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (8, '解析力学とその数理ゼミ', '{"theme":"解析力学とその数理","level":"大学教養レベルの数学を知っている人","goals":"解析力学とその数理を理解する","prerequisites":"大学教養レベルの数学","materials":"山本 義隆・中村 孔一 「解析力学Ⅰ・Ⅱ」","organizer":"東京大学教養学部3年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"2024年5月〜","frequency":"週1回","schedule":"木曜6限","conditions":"学生","currentSize":"6人","capacity":"未定","description":"解析力学とその数理を学びます。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000008-%E8%A7%A3%E6%9E%90%E5%8A%9B%E5%AD%A6%E3%81%A8%E3%81%9D%E3%81%AE%E6%95%B0%E7%90%86%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (7, '公理的集合論ゼミ', '{"theme":"公理的集合論","level":"順序数論の初歩を知っている人","goals":"強制法のさわりまで","prerequisites":"順序数論の初歩と、できれば、数理論理学の初歩","materials":"キューネン「集合論」(旧版)","organizer":"東京大学教養学部3年有志","format":"対面","venue":"東京大学本郷キャンパス","period":"2023年夏〜","frequency":"週1回","schedule":"日曜午前","conditions":"学生","currentSize":"3人","capacity":"未定","description":"強制法のさわりまで読みます。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000007-%E5%85%AC%E7%90%86%E7%9A%84%E9%9B%86%E5%90%88%E8%AB%96%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (6, '偏微分方程式ゼミ', '{"theme":"偏微分方程式","level":"大学教養レベルの数学を知っている人","goals":"Evansの有名なPDEの教科書を読む","prerequisites":"大学教養レベルの数学","materials":"L. C. Evans \"Partial Differential Equations\"","organizer":"東京大学教養学部3年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"2023年秋〜","frequency":"週1回","schedule":"木曜3限(13:15-14:45)","conditions":"学生","currentSize":"2人","capacity":"未定","description":"L. C. Evans \"Partial Differential Equations\"を読みます。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000006-%E5%81%8F%E5%BE%AE%E5%88%86%E6%96%B9%E7%A8%8B%E5%BC%8F%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (5, '位相ベクトル空間・超関数・核ゼミ', '{"theme":"位相ベクトル空間・超関数・核","level":"数学科3年程度の解析学を知っている人","goals":"関数空間とその双対空間の位相やテンソル積に親しむ","prerequisites":"数学科3年程度の解析学","materials":"トレーブ「位相ベクトル空間・超関数・核」","organizer":"東京大学教養学部3年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"2024年2月〜","frequency":"週1回","schedule":"水曜午後","conditions":"学生","currentSize":"2人","capacity":"未定","description":"位相ベクトル空間としての関数空間とその双対空間の性質をまなびます。最終的には、関数空間のテンソル積、シュワルツの核定理などに到達することを目標とします。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000005-%E4%BD%8D%E7%9B%B8%E3%83%99%E3%82%AF%E3%83%88%E3%83%AB%E7%A9%BA%E9%96%93%E8%B6%85%E9%96%A2%E6%95%B0%E6%A0%B8%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (4, '物理化学ゼミ', '{"theme":"物理化学","level":"初学者","goals":"分子間に働く相互作用や表面現象を中心に、様々な物理化学的な現象を定性的・定量的に理解する","prerequisites":"特にないが大学教養レベルの物理・化学の知識があると好ましい","materials":"J.N. イスラエルアチヴィリ 著、大島 広行 訳「分子間力と表面力」","organizer":"東京大学教養学部化学部","format":"対面","venue":"東京大学駒場キャンパス","period":"5月〜未定","frequency":"週1回","schedule":"金曜3限(13:15-14:45)","conditions":"東京大学の学生","currentSize":"5人","capacity":"7-8人程度","description":"基本的には教科書をみんなで読み進めていくという形式をとっています。このため、教科書は買うか借りるかなどしてご自分のものを用意してください。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000004-%E7%89%A9%E7%90%86%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (1, '漢検勉強会', '{"theme":"漢字","level":"不問","goals":"漢検準1級・1級の取得、漢字の知識の習得","prerequisites":"漢検2級程度の知識","materials":"参考書・問題集・辞書等は各自用意","organizer":"東京大学2年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"4月下旬〜未定","frequency":"週3回(いずれか1回以上に自由参加)","schedule":"月曜4限(15:10-16:40)、水曜3限(13:15-14:45)、木曜2限(10:25-11:55)、金曜3限(14:00-15:30)","conditions":"学生","currentSize":"10人程度","capacity":"なし","description":"主に漢検準1級・1級の取得を目指す人向けの勉強会です。それぞれに問題を解くのがメインですが、分からないことについて聞いたり一緒に調べたり、漢字の体系的な知識について教え合ったりといった活動も想定しています。"}', 'approved', 'open', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000001-%E6%BC%A2%E6%A4%9C%E5%8B%89%E5%BC%B7%E4%BC%9A', '2026-11-11T00:00:00.000Z'),
  (29, '有機化学ゼミ', '{"theme":"有機化学","level":"高校化学履修者向け","goals":"有機化学を扱えるようになる","prerequisites":"なし","materials":"マクマリー有機化学 9,10版","organizer":"Wathematica","format":"対面","venue":"早稲田大学","period":"2025年6月〜","frequency":"週1回","schedule":"火曜5限","conditions":"早稲田大学の学生","currentSize":"6人","capacity":"未定","description":"授業の予復習など"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000029-%E6%9C%89%E6%A9%9F%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (28, '分子軌道法ゼミ', '{"theme":"分子軌道法","level":"B2化学系","goals":"分子軌道法の理解","prerequisites":"特になし","materials":"友田修司『分子軌道法-定性的MO 法で化学を考える-』東京大学出版会","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜","frequency":"週に1回","schedule":"毎週金曜か日曜","conditions":"特になし","currentSize":"4人","capacity":"未定","description":"分子軌道法の基本的な考え方を一通り終え，具体的な分子への適用に入りました．初版の本を使う宿命かもしれませんが，誤植と思われる部分や，誤解が生じやすい部分も少なくなかったので，主体的・批判的に読み，正確に理解できるように努めました"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000028-%E5%88%86%E5%AD%90%E8%BB%8C%E9%81%93%E6%B3%95%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (23, '心理学ゼミ', '{"theme":"心理学","level":"初学者","goals":"心理学史、臨床心理学を学ぶ","prerequisites":"特になし","materials":"特になし","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜","frequency":"1か月に一度","schedule":"参加者で日程調整","conditions":"特になし","currentSize":"6人","capacity":"未定","description":"特になし"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000023-%E5%BF%83%E7%90%86%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (21, 'ゲージ理論ゼミ', '{"theme":"ゲージ理論","level":"初学者","goals":"数学のゲージ理論に入門する。","prerequisites":"多様体","materials":"茂木勇・伊藤光弘『復刊 微分幾何学とゲージ理論』","organizer":"Wathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"2025.4〜未定","frequency":"週1","schedule":"木曜5限(17:00-18:40)","conditions":"早稲田大学の学生","currentSize":"4人","capacity":"未定","description":"ゲージ理論を学ぶための微分幾何学の知識を身につけて、数学のゲージ理論に入門することを目指す。また、物理のゲージ理論の数学的な構造を理解する。"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000021-%E3%82%B2%E3%83%BC%E3%82%B8%E7%90%86%E8%AB%96%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (20, '流体力学ゼミ', '{"theme":"量子化学ゼミ","level":"難　行間を埋めるためにベクトル解析の知識が必要","goals":"一冊を読み込む","prerequisites":"ベクトル解析","materials":"巽友正著　流体力学","organizer":"Wathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"2025.6月中旬〜","frequency":"週1","schedule":"金曜3限(13:10〜14:50)","conditions":"早稲田大学の学生","currentSize":"5人","capacity":"なし","description":"流体力学の名著を読みながら輪講する。流体力学を深く理解する。"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000020-%E6%B5%81%E4%BD%93%E5%8A%9B%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (18, '量子化学ゼミ', '{"theme":"量子化学ゼミ","level":"化学専攻の学部生","goals":"量子化学計算のシステムを手で解いて学ぶ","prerequisites":"学部1年生までの化学、量子力学の初歩的知識","materials":"手で解く量子化学（中井浩巳）","organizer":"Wathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"2025.4〜現在","frequency":"週1","schedule":"月5限（17:00〜18:40）","conditions":"早稲田大学の学生","currentSize":"4人","capacity":"5人程度","description":"量子化学を専攻にしたい学生と、数学科、物理系の学科の学生たちが集まって、量子化学計算を手で解くことを目標にしています。"}', 'approved', 'paused', 'active', 'https://sites.google.com/view/atlasez-semi/0000018-%E9%87%8F%E5%AD%90%E5%8C%96%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (15, '量子力学ゼミ', '{"theme":"量子力学ゼミ","level":"完全な初学者","goals":"非物理学科の人たちが量子力学についてあらかた理解する","prerequisites":"線形代数","materials":"佐藤博彦「初歩から学ぶ量子力学」","organizer":"Wathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"2024.3〜現在","frequency":"火曜6限","schedule":"水3(13:00-14:30)","conditions":"Wathematicaに所属する者","currentSize":"4人","capacity":"未定","description":"初学者たちが、非物理学科の人向けに書かれた量子力学の本を読んで基礎的なところから理解することを目指しています"}', 'approved', 'paused', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000015-%E9%87%8F%E5%AD%90%E5%8A%9B%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (30, '物性と場の量子論ゼミ', '{"theme":"物性物理学と場の量子論の境界領域","level":"初学者","goals":"物性理論において場の量子論の手法がどのように有用なのかを知る","prerequisites":"基礎的な統計力学、量子力学の知識等。場の量子論の予備知識は仮定しない","materials":"Condensed Matter Field Theory, 2nd (3rd) Edition (Altland & Simons)","organizer":"第29回数物セミナー　場の量子論2班","format":"オンライン＋対面","venue":"数物セミナー合宿、Discord VC","period":"2025年8月上旬〜","frequency":"週1,2回","schedule":"週による","conditions":"量子力学、統計力学の基礎を固めた人","currentSize":"4人","capacity":"4人","description":"参加者は全員物性理論に関心がある人たちで、物性理論と場の量子論の関わりについて書かれた本を読んで、物性理論に対する理解を深めつつ、場の量子論の手法を学ぶことを目的としています。\n参加者の中にはAdS/CMT（CFTではなく）に興味を持っているものがおり、場の量子論自体も深く学びたいと考えているため、その第一歩になればと考えている側面もあります。"}', 'approved', 'closed', 'planned', 'https://sites.google.com/view/atlasez-semi/0000030-%E7%89%A9%E6%80%A7%E3%81%A8%E5%A0%B4%E3%81%AE%E9%87%8F%E5%AD%90%E8%AB%96%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (27, 'マッカーリサイモンゼミ', '{"theme":"物理化学","level":"B1~B2化学系","goals":"物理化学の理解","prerequisites":"特になし","materials":"D.A.McQuarrie，J.D.Simon『マッカーリ・サイモン物理化学(上)』東京化学同人","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜7月","frequency":"週に1回","schedule":"参加者で日程調整","conditions":"特になし","currentSize":"6人","capacity":"未定","description":"6 月は，第4 章（量子力学の仮説と一般原理）と第5 章（調和振動子と剛体回転子）を主に扱いました"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000027-%E3%83%9E%E3%83%83%E3%82%AB%E3%83%BC%E3%83%AA%E3%82%B5%E3%82%A4%E3%83%A2%E3%83%B3%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (26, '理学部1セメの数学ゼミ', '{"theme":"解析学、線形数学","level":"B1~B2化学系、B1物理系","goals":"理学部１セメでの数学で単位を取ること","prerequisites":"特になし","materials":"三宅敏恒『入門微分積分』培風館\n村上正康・佐藤恒雄・野沢宗平・稲葉尚志『教養の線形代数六訂版』培風館\n授業で使用している教科書を使用してます．","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜7月","frequency":"週に1回","schedule":"参加者で日程調整","conditions":"特になし","currentSize":"6人","capacity":"未定","description":"特になし"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000026-%E7%90%86%E5%AD%A6%E9%83%A81%E3%82%BB%E3%83%A1%E3%81%AE%E6%95%B0%E5%AD%A6%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (25, '物理数学（金）ゼミ', '{"theme":"物理数学","level":"B1物理系","goals":"よりスマートな解法や導出を追求したり，物理でどう応用されるのかを調べたりしていきたい","prerequisites":"特になし","materials":"石川洋『はじめての物理数学』東北大学出版会","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜7月","frequency":"週に1回","schedule":"毎週金曜","conditions":"特になし","currentSize":"4人","capacity":"未定","description":"基本的にはまったり，雑談を混ぜながら進めていますが，よりスマートな解法や導出を追求したり，物理でどう応用されるのかを調べたりしていきたいです．疎かになりがちな演習にも力を入れて，着実に技を身につけていけるようなゼミにできたらと思います．"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000025-%E7%89%A9%E7%90%86%E6%95%B0%E5%AD%A6%E9%87%91%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (24, '物理数学（水）ゼミ', '{"theme":"物理数学","level":"B1物理系","goals":"授業で疑問に感じた部分や何となく消化不良に感じた部分について議論したり調べたりする","prerequisites":"特になし","materials":"石川洋『はじめての物理数学』東北大学出版会","organizer":"ずんだゼミ","format":"対面","venue":"東北大学川内キャンパス","period":"2025年4月〜7月","frequency":"週に1回","schedule":"毎週水曜","conditions":"特になし","currentSize":"3人","capacity":"未定","description":"授業で疑問に感じた部分や何となく消化不良に感じた部分について議論したり調べたりする活動を積極的に行いました．疑問が解消したり，また別の見方をできるようになったりと，普段の授業の延長として非常に有意義な活動となりました．"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000024-%E7%89%A9%E7%90%86%E6%95%B0%E5%AD%A6%E6%B0%B4%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (22, '粘性解ゼミ', '{"theme":"粘性解ゼミ","level":"B4~M1の物理学科、数学科","goals":"数理物理、経済、さらに最近では最適輸送などの情報分野において現れる、部分積分の手法が使えない（退化）楕円型、放物型偏微分方程式における粘性解というある種の弱解の有用性を学ぶ","prerequisites":"ソボレフ空間をはじめとする関数解析、基本的な偏微分方程式論","materials":"・Nikos Katzourakis ,  An Introduction To Viscosity Solutions for Fully Nonlinear PDE with Applications to Calculus of Variations in L∞ , Springer\n・小池茂昭, 粘性解 ―比較原理を中心に― , 共立出版","organizer":"Wathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"4月〜8月","frequency":"2週間に一度","schedule":"木曜3限","conditions":"Wathematicaのメンバー","currentSize":"3人","capacity":"未定","description":"ラフパスや確率偏微分方程式との関わりも深い分野のため、物理学科、数学科などで自由に自分の知識を交えた交流もしていきたい。"}', 'approved', 'closed', 'active', 'https://sites.google.com/view/atlasez-semi/0000022-%E7%B2%98%E6%80%A7%E8%A7%A3%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (19, '作用素環論ゼミ', '{"theme":"作用素環論","level":"初学者が中心","goals":"作用素環論の基礎事項を学習し、数理物理学や非可換幾何学への応用を目指す","prerequisites":"函数解析学の基礎","materials":"戸松玲治『作用素環論入門』共立出版","organizer":"理工系学術サークルWathematica","format":"対面","venue":"早稲田大学西早稲田キャンパス","period":"2024年11月頃～継続中","frequency":"週1回","schedule":"火曜日2限(10:40～12:20)","conditions":"早稲田大学の学生","currentSize":"4人","capacity":"特に指定しない","description":"前提知識として測度論、位相線型空間論を事前に参加者でゼミ形式で学習しました。その後、C^*環の基礎事項から学習し、現在はGelfand-Naimarkの定理の応用を見ています。今後Von Neumann環の理論を学び、量子論の数学的な基礎付け或いは非可換幾何学や粗幾何学への応用を目標にセミナーを続けています。参加者は数学専攻のみならず物理専攻の学生もいます。"}', 'approved', 'closed', 'ended', 'https://sites.google.com/view/atlasez-semi/0000019-%E4%BD%9C%E7%94%A8%E7%B4%A0%E7%92%B0%E8%AB%96%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (17, 'フォック空間と量子場ゼミ', '{"theme":"フォック空間と量子場ゼミ","level":"完全な初学者","goals":"フォック空間の数学的に厳密な取り扱いについて学び、場の量子論への応用を学ぶ。","prerequisites":"関数解析（「ヒルベルト空間と量子力学」程度）","materials":"「フォック空間と量子場」（新井朝雄）","organizer":"数物セミナー28th　数理物理班","format":"オンライン中心＋対面","venue":"Discord","period":"2025年2月〜","frequency":"週1回","schedule":"参加者の都合による","conditions":"フォック空間の数学的取り扱いに興味のある学生","currentSize":"5人","capacity":"5人程度","description":"固定された数の粒子のダイナミクスを記述する量子力学はある一つのHilbert空間によって記述されますが、場の量子論に移行し粒子の生成消滅を考えるようになると、それでは不十分でFock空間を考える必要が出てきます。\n本ゼミでは、単一のHIlbert空間やそれ上の線形作用素を扱う関数解析学から一歩進んで、Fock空間の数学的取り扱いを学び、場の量子論を数学的に厳密な形で理解することを目標にしています…"}', 'approved', 'closed', 'paused', 'https://sites.google.com/view/atlasez-semi/0000017-%E3%83%95%E3%82%A9%E3%83%83%E3%82%AF%E7%A9%BA%E9%96%93%E3%81%A8%E9%87%8F%E5%AD%90%E5%A0%B4%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (14, '田崎統計力学I, II', '{"theme":"田崎統計力学I, II","level":"統計力学の完全な初学者。統計学も初学で良い。解析力学や量子力学の基本的な知識があると良い。","goals":"平衡統計力学の基本的な所の習得","prerequisites":"特になし。","materials":"田崎統計力学I, II","organizer":"physics lab.","format":"対面","venue":"東京大学駒場キャンパスまたは本郷キャンパス","period":"半セメスター","frequency":"週1","schedule":"水3(13:00-14:30)","conditions":"終了","currentSize":"7人","capacity":"7人","description":"本の内容を理解しよう。みんな統計力学初学でした。"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000014-%E7%94%B0%E5%B4%8E%E7%B5%B1%E8%A8%88%E5%8A%9B%E5%AD%A6i-ii', '2026-11-11T00:00:00.000Z'),
  (11, '集合と位相ゼミ', '{"theme":"集合と位相","level":"完全な初学者","goals":"集合と位相の基礎がわかる","prerequisites":"大学1年生の数学の知識","materials":"自作の教科書","organizer":"ずんだゼミ","format":"対面","venue":"東北大学青葉山キャンパス","period":"2024年12月〜未定","frequency":"週1回","schedule":"不定期","conditions":"東北大学の学生","currentSize":"5人","capacity":"未定","description":"経緯はよく分からないが、数学科3年の方が工学部や数学専攻以外の人に講義する形式"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000011-%E9%9B%86%E5%90%88%E3%81%A8%E4%BD%8D%E7%9B%B8%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (3, '一般確率論ゼミ', '{"theme":"一般確率論","level":"完全な初学者","goals":"一般確率論の基礎的な知識をつけ、下のテキストを読み切る","prerequisites":"量子力学の基礎","materials":"M. Plávala \"General probabilistic theories: An introduction\"\n(https://arxiv.org/abs/2103.07469)","organizer":"東京大学2年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"6月上旬〜8月中旬、それ以降は未定","frequency":"週1回","schedule":"金曜4限(15:10-16:40)","conditions":"学生","currentSize":"7人程度","capacity":"未定","description":"量子情報の授業を聴講している2年生を中心に一般確率論について勉強します。"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000003-%E4%B8%80%E8%88%AC%E7%A2%BA%E7%8E%87%E8%AB%96%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z'),
  (2, 'リー代数ゼミ', '{"theme":"リー代数","level":"完全な初学者","goals":"リー代数の基礎の習得、物理的応用の理解","prerequisites":"大学教養レベルの線形代数","materials":"佐藤 肇「リー代数入門 ー線形代数の続編としてー」","organizer":"東京大学2年有志","format":"対面","venue":"東京大学駒場キャンパス","period":"6月上旬〜8月中旬、それ以降は未定","frequency":"週1回","schedule":"木曜2限(10:25-11:55)","conditions":"学生","currentSize":"5人程度","capacity":"10人程度","description":"数学の勉強をしたい2年生で集まって、大学教養レベルの線形代数の発展としてリー代数を勉強してみようということになりました。初学者でなくても歓迎です、色々教えてください。"}', 'approved', 'closed', 'unknown', 'https://sites.google.com/view/atlasez-semi/0000002-%E3%83%AA%E3%83%BC%E4%BB%A3%E6%95%B0%E3%82%BC%E3%83%9F', '2026-11-11T00:00:00.000Z');
